create or replace function public.get_business_product_access(p_business_id uuid) returns table(business_id uuid,business_tier public.business_tier,location_count bigint,location_limit integer,enterprise_enabled boolean) language sql security definer set search_path=public as $$ select b.id,b.business_tier,count(l.id)::bigint,case when b.business_tier='growth' then 5 else null end::integer,(b.business_tier in ('growth','enterprise')) from public.businesses b left join public.locations l on l.business_id=b.id and coalesce(l.is_active,true)=true where b.id=p_business_id and (exists(select 1 from public.app_business_memberships m where m.business_id=b.id and m.user_id=auth.uid()) or coalesce((select p.is_admin from public.profiles p where p.id=auth.uid()),false)) group by b.id,b.business_tier; $$; revoke all on function public.get_business_product_access(uuid) from public; grant execute on function public.get_business_product_access(uuid) to authenticated;
create or replace function public.enforce_growth_location_cap() returns trigger language plpgsql security definer set search_path=public as $$ declare v_tier public.business_tier; v_count integer; v_admin boolean; begin if new.business_id is null then return new; end if; select business_tier into v_tier from public.businesses where id=new.business_id; if v_tier <> 'growth' then return new; end if; select coalesce(is_admin,false) into v_admin from public.profiles where id=auth.uid(); if v_admin then return new; end if; select count(*) into v_count from public.locations where business_id=new.business_id and coalesce(is_active,true)=true and id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid); if v_count >= 5 then raise exception 'Business Growth is limited to 5 active locations'; end if; return new; end; $$;
drop trigger if exists trg_growth_location_cap on public.locations; create trigger trg_growth_location_cap before insert or update of business_id,is_active on public.locations for each row when (new.business_id is not null) execute function public.enforce_growth_location_cap();
